<script setup>
import { computed, nextTick, onBeforeUnmount, ref, useId, watch } from 'vue'
import { api } from '../../api.js'
import UiIcon from '../ui/UiIcon.vue'
import { agentCanStop, agentProgress, agentStateLabel, agentTreeRows } from '../../lib/agentTeam.js'
import { activationRecords, agentResponsibility, agentTone, layoutAgentTree, monitorRows, recordPresentation, teamSummary } from '../../lib/agentTeamMonitor.js'

const props = defineProps({ team: { type: Object, default: null }, selectedId: { type: String, default: '' }, loading: Boolean,
  error: { type: String, default: '' }, acting: { type: String, default: '' }, visible: { type: Boolean, default: true } })
const emit = defineEmits(['refresh', 'stop', 'attention'])
const titleId = useId(), modal = ref(null), trigger = ref(null), opened = ref(false), chosenId = ref('')
const query = ref(''), filter = ref('all'), view = ref('graph'), recordTab = ref(false), recordBusy = ref(false), recordError = ref(''), evidence = ref(null)
const matchingTeam = computed(() => props.team?.lead?.session_id === props.selectedId ? props.team : null)
const rows = computed(() => agentTreeRows(matchingTeam.value)), summary = computed(() => teamSummary(matchingTeam.value))
const filtered = computed(() => monitorRows(matchingTeam.value, query.value, filter.value))
const graph = computed(() => layoutAgentTree(filtered.value.rows))
const chosen = computed(() => rows.value.find(row => row.session_id === chosenId.value) || rows.value[0] || null)
const chosenParent = computed(() => rows.value.find(row => row.session_id === chosen.value?.parent_session_id))
const responsibility = computed(() => agentResponsibility(chosen.value, rows.value))
let request = 0, previousFocus = null, disposed = false
const activationKey = computed(() => `${chosen.value?.session_id || ''}:${chosen.value?.activation_id || 0}`)
function choose(agent) { chosenId.value = agent.session_id; recordTab.value = false }
async function openMonitor() {
  previousFocus = document.activeElement; opened.value = true
  chosenId.value = props.selectedId; recordTab.value = false
  await nextTick()
  if (!opened.value || !props.visible || disposed) return
  if (!modal.value.open) modal.value.showModal()
  modal.value.focus({ preventScroll: true })
}
function closeMonitor(restore = true) {
  opened.value = false; request++; recordBusy.value = false; evidence.value = null; modal.value?.close()
  if (restore && previousFocus?.isConnected) previousFocus.focus({ preventScroll: true })
  previousFocus = null
}
function attention() { const id = chosen.value?.session_id; closeMonitor(); emit('attention', id) }
function keepFocus(event) {
  if (event.key !== 'Tab') return
  const controls = [...modal.value.querySelectorAll('button:not(:disabled), input:not(:disabled), select:not(:disabled), textarea:not(:disabled), a[href], summary, [tabindex="0"]')].filter(node => node.getClientRects().length)
  const first = controls[0], last = controls.at(-1)
  if (!first) { event.preventDefault(); return }
  if (event.shiftKey && (document.activeElement === first || document.activeElement === modal.value)) { event.preventDefault(); last.focus() }
  else if (!event.shiftKey && (document.activeElement === last || document.activeElement === modal.value)) { event.preventDefault(); first.focus() }
}
async function readRecords() {
  const agent = chosen.value
  if (!agent || !agent.activation_id || recordBusy.value) return
  const key = activationKey.value, root = props.selectedId, version = ++request
  recordBusy.value = true; recordError.value = ''; evidence.value = null
  try {
    const events = await api.events(agent.session_id)
    if (!disposed && opened.value && request === version && props.selectedId === root && activationKey.value === key) {
      evidence.value = activationRecords(Array.isArray(events) ? events : [], agent.activation_id)
    }
  } catch (cause) {
    if (request === version && props.selectedId === root && activationKey.value === key) recordError.value = cause.message || '读取执行记录失败，请重试'
  } finally { if (request === version) recordBusy.value = false }
}
function showRecords() { recordTab.value = true; if (!evidence.value) void readRecords() }
watch(activationKey, () => { request++; evidence.value = null; recordError.value = ''; recordBusy.value = false; if (recordTab.value && opened.value) void readRecords() })
watch(() => props.selectedId, () => { closeMonitor(false); chosenId.value = ''; query.value = ''; filter.value = 'all'; recordTab.value = false })
watch(() => props.visible, visible => { if (!visible) closeMonitor(false) })
onBeforeUnmount(() => { disposed = true; closeMonitor(false) })
</script>

<template>
  <button ref="trigger" type="button" class="monitor-trigger" aria-haspopup="dialog" @click="openMonitor"><UiIcon name="git-branch" :size="13" />协作视图</button>
  <Teleport to="body">
    <dialog ref="modal" class="team-monitor" tabindex="-1" :aria-labelledby="titleId" @cancel.prevent="closeMonitor()" @keydown.stop="keepFocus">
      <div v-if="opened" class="monitor-shell">
        <header class="monitor-heading">
          <div class="monitor-identity"><span class="monitor-symbol"><UiIcon name="git-branch" :size="22" /></span><div><div class="monitor-eyebrow">CODE-AGENT / 当前对话</div><h2 :id="titleId">多智能体协作</h2></div></div>
          <div class="heading-actions"><span class="update-label"><i />状态随任务更新</span><button :disabled="loading" @click="emit('refresh')"><UiIcon name="refresh" :size="14" />{{ loading ? '刷新中' : '刷新' }}</button><button class="monitor-close" aria-label="关闭协作视图" @click="closeMonitor()"><UiIcon name="close" :size="18" /></button></div>
        </header>
        <div class="monitor-statusbar" role="status">
          <span><b>{{ summary.total }}</b> 个子任务</span><span class="metric-running"><i /><b>{{ summary.running }}</b> 执行中</span><span><i class="dot-queued" /><b>{{ summary.queued }}</b> 排队</span><span><i class="dot-waiting" /><b>{{ summary.waiting }}</b> 等待</span><span><i class="dot-completed" /><b>{{ summary.completed }}</b> 已完成</span>
          <span class="project-limit">项目共享并发上限 <b>{{ matchingTeam?.limits?.max_parallel ?? '—' }}</b><span> · 深度上限 {{ matchingTeam?.limits?.max_depth ?? '—' }}</span></span>
        </div>
        <p v-if="error" class="monitor-error" role="alert">{{ error }} <button :disabled="loading" @click="emit('refresh')">重试</button></p>
        <div class="monitor-body">
          <section class="relation-panel" aria-label="智能体委派关系">
            <div class="relation-toolbar"><div class="view-switch" aria-label="展示方式"><button :aria-pressed="view === 'graph'" @click="view = 'graph'"><UiIcon name="git-branch" :size="13" />关系图</button><button :aria-pressed="view === 'list'" @click="view = 'list'"><UiIcon name="menu" :size="13" />列表</button></div><label class="monitor-search"><UiIcon name="search" :size="14" /><span class="sr-only">搜索子任务</span><input v-model="query" placeholder="搜索任务、文件或理由" /></label></div>
            <div class="relation-filters" aria-label="任务状态筛选"><button v-for="item in [{id:'all',label:'全部任务'},{id:'active',label:'进行中'},{id:'attention',label:'需关注'}]" :key="item.id" :aria-pressed="filter === item.id" @click="filter = item.id">{{ item.label }}<span v-if="item.id === 'attention' && summary.attention">{{ summary.attention }}</span></button><span class="relation-caption">连线表示任务委派</span></div>
            <div v-if="!matchingTeam" class="monitor-empty" role="status"><UiIcon name="git-branch" :size="30" /><strong>{{ loading ? '正在读取协作状态' : '暂未获取当前对话的协作状态' }}</strong><button v-if="!loading" @click="emit('refresh')">重新读取</button></div>
            <template v-else>
              <p v-if="!summary.total" class="empty-inline">当前由主智能体处理。需要分工时，子任务会出现在这里。</p>
              <p v-else-if="!filtered.matched" class="empty-inline">没有符合条件的子任务。<button @click="query = ''; filter = 'all'">清除筛选</button></p>
              <div v-if="view === 'graph'" class="graph-scroll" tabindex="0" aria-label="委派关系图，可滚动查看" :aria-describedby="`${titleId}-legend`">
                <div class="graph-stage" :style="{width:`${graph.width}px`,height:`${graph.height}px`}">
                  <svg class="graph-edges" :width="graph.width" :height="graph.height" aria-hidden="true"><path v-for="edge in graph.edges" :key="edge.id" :d="edge.path" :class="{ 'edge-selected': edge.target === chosen?.session_id || edge.source === chosen?.session_id }" /></svg>
                  <button v-for="agent in graph.nodes" :key="agent.session_id" class="agent-node" :class="[`tone-${agentTone(agent)}`, {'node-selected':agent.session_id === chosen?.session_id,'node-context':agent.contextOnly}]" :style="{left:`${agent.x}px`,top:`${agent.y}px`,width:`${agent.width}px`,height:`${agent.height}px`}" :aria-pressed="agent.session_id === chosen?.session_id" :data-monitor-agent="agent.session_id" @click="choose(agent)">
                    <span class="node-topline"><span class="node-role">{{ agent.role === 'lead' ? 'LEAD · 主智能体' : `子任务 · 第 ${agent.depth ?? agent.indent} 层` }}</span><UiIcon :name="agent.role === 'lead' ? 'sparkles' : 'git-branch'" :size="13" /></span>
                    <strong :title="agent.title">{{ agent.role === 'lead' ? '主对话协调者' : agent.title || '子任务' }}</strong><span class="node-status"><i />{{ agentStateLabel(agent) }}<small v-if="agent.current_tool">{{ agent.current_tool }}</small></span>
                  </button>
                </div>
              </div>
              <div v-else class="agent-list" aria-label="智能体任务列表"><button v-for="agent in filtered.rows" :key="agent.session_id" :class="[`tone-${agentTone(agent)}`,{'list-selected':agent.session_id === chosen?.session_id}]" :aria-pressed="agent.session_id === chosen?.session_id" :data-monitor-agent="agent.session_id" @click="choose(agent)"><span class="list-depth">{{ agent.role === 'lead' ? 'Lead' : `L${agent.depth ?? agent.indent}` }}</span><span class="list-title"><strong>{{ agent.role === 'lead' ? '主对话协调者' : agent.title || '子任务' }}</strong><small>{{ agent.current_tool || agent.blocked_reason || '—' }}</small></span><span class="node-status"><i />{{ agentStateLabel(agent) }}</span></button></div>
            </template>
            <footer :id="`${titleId}-legend`" class="relation-footer"><span><i class="dot-completed" />已完成表示执行结束，验收结果在任务详情中查看</span><span>Lead 不占子任务并发名额</span></footer>
          </section>
          <aside class="agent-inspector" aria-label="选中任务详情">
            <template v-if="chosen">
              <div class="inspector-header"><span class="inspector-kicker">{{ chosen.role === 'lead' ? '主智能体' : '子任务详情' }}</span><span class="state-pill" :class="`tone-${agentTone(chosen)}`"><i />{{ agentStateLabel(chosen) }}</span><h3>{{ chosen.role === 'lead' ? '主对话协调者' : chosen.title || '子任务' }}</h3><p v-if="chosenParent">由 {{ chosenParent.role === 'lead' ? '主智能体' : chosenParent.title || '上级任务' }} 委派</p><p v-else-if="chosen.role !== 'lead'">上级任务未在当前快照中显示</p></div>
              <div class="inspector-switch" aria-label="任务详情内容"><button :aria-pressed="!recordTab" @click="recordTab = false">任务概览</button><button :aria-pressed="recordTab" @click="showRecords">执行记录</button></div>
              <div v-if="!recordTab" class="inspector-content">
                <div v-if="chosen.blocked_reason || ['attention','failed'].includes(agentTone(chosen))" class="attention-box" :class="`tone-${agentTone(chosen)}`"><UiIcon name="warning" :size="16" /><div><strong>{{ chosen.state === 'failed' ? '任务需要检查' : '任务正在等待' }}</strong><p>{{ chosen.blocked_reason || chosen.error || '需要你处理待审批操作或提问' }}</p><button v-if="agentTone(chosen) === 'attention'" @click="attention">前往处理申请<UiIcon name="arrow-right" :size="13" /></button></div></div>
                <dl class="execution-facts"><div><dt>本轮执行</dt><dd>{{ chosen.activation_id ? `第 ${chosen.activation_id} 次` : '尚未开始' }}</dd></div><div><dt>当前工具</dt><dd>{{ chosen.current_tool || '—' }}</dd></div><div><dt>执行耗时</dt><dd>{{ agentProgress(chosen).elapsed || '—' }}</dd></div><div><dt>执行权限</dt><dd>{{ ({'read-only':'只读','workspace-write':'工作区写入','full-access':'完全权限'})[chosen.effective_permission] || '—' }}</dd></div><div v-if="chosen.role !== 'lead'"><dt>产出验收</dt><dd>{{ ({accepted:'已接受',rejected:'已驳回',pending:'待核验',none:'未记录'})[chosen.audit?.decision] || '未记录' }}</dd></div></dl>
                <section class="detail-section"><h4>任务目标</h4><p>{{ chosen.last_task_message || (chosen.role === 'lead' ? '理解当前请求，直接执行或委派独立子任务，整合结果并交付。' : '暂无任务目标记录。') }}</p></section>
                <section class="detail-section file-responsibility"><h4>负责文件<span>{{ responsibility.scopeLabel }}</span></h4>
                  <p v-if="!responsibility.declared">本轮未声明文件责任范围。</p>
                  <p v-else-if="responsibility.readOnly">只读分析与核验，不负责修改文件。</p>
                  <ul v-else class="file-scope-list"><li v-for="path in responsibility.paths" :key="path"><code>{{ path === '.' ? '整个工作区（含子目录）' : path }}</code><small v-if="path.endsWith('/')">目录及其子文件</small></li></ul>
                </section>
                <section class="detail-section delegation-reason"><h4>派工理由</h4><p>{{ responsibility.reason || '未声明' }}</p></section>
                <section class="detail-section file-ownership"><h4>文件持有情况</h4><p>{{ responsibility.ownershipLabel }}</p>
                  <ul v-if="responsibility.blockers.length" class="ownership-holders"><li v-for="(owner, index) in responsibility.blockers" :key="owner.session_id || `anonymous-${index}`"><p>等待 {{ owner.title }} 释放</p><small v-if="owner.session_id">{{ owner.session_id }}</small><ul class="file-scope-list"><li v-for="path in owner.paths" :key="path"><code>{{ path === '.' ? '整个工作区（含子目录）' : path }}</code></li></ul></li></ul>
                  <template v-if="responsibility.dependencies.length"><p class="dependency-caption">前置执行</p><ul class="dependency-list"><li v-for="dependency in responsibility.dependencies" :key="`${dependency.session_id}:${dependency.activation_id}`">{{ dependency.title }} · 第 {{ dependency.activation_id }} 次<small>{{ dependency.session_id }}</small></li></ul></template>
                </section>
                <section v-if="chosen.result" class="detail-section"><h4>最新结果<span>执行报告</span></h4><pre>{{ chosen.result }}</pre></section><section v-if="chosen.error" class="detail-section result-error"><h4>执行错误</h4><pre>{{ chosen.error }}</pre></section>
                <details class="identity-details"><summary>查看执行身份</summary><dl><dt>会话</dt><dd>{{ chosen.session_id }}</dd><dt>工作树</dt><dd>{{ chosen.tree_id || 'main' }}</dd></dl></details>
              </div>
              <div v-else class="inspector-content trace-content"><div class="trace-heading"><span>第 {{ chosen.activation_id || 0 }} 次执行</span><button :disabled="recordBusy || !chosen.activation_id" @click="readRecords"><UiIcon name="refresh" :size="13" />{{ recordBusy ? '读取中' : '刷新记录' }}</button></div><p v-if="recordError" class="monitor-error" role="alert">{{ recordError }}</p><p v-if="!chosen.activation_id" class="trace-empty">任务尚未开始，暂无执行记录。</p><p v-else-if="recordBusy" class="trace-empty" role="status">正在读取本轮执行证据…</p><template v-else-if="evidence"><p v-if="evidence.boundary === 'missing'" class="trace-empty">未找到本轮执行边界，暂不展示其他轮次的记录。</p><p v-else-if="!evidence.records.length" class="trace-empty">本轮尚无工具或结束记录。</p><p v-if="evidence.omitted" class="trace-empty">显示本轮最近 150 条记录。</p><ol class="execution-trace"><li v-for="event in evidence.records" :key="event.seq"><span class="trace-label">{{ recordPresentation(event).label }}<small>#{{ event.seq }}</small></span><strong>{{ recordPresentation(event).title }}</strong><pre>{{ recordPresentation(event).text }}</pre></li></ol></template></div>
              <footer class="inspector-footer"><button v-if="chosen.role !== 'lead' && agentCanStop(chosen)" class="stop-task" :disabled="!!acting" @click="emit('stop', chosen.session_id)"><UiIcon name="close" :size="13" />{{ acting === chosen.session_id ? '正在停止…' : '停止此任务及后代' }}</button><span v-else>{{ chosen.role === 'lead' ? '在主对话中继续协作' : '查看结果后，由主智能体整合交付' }}</span></footer>
            </template>
          </aside>
        </div>
      </div>
    </dialog>
  </Teleport>
</template>

<style scoped>
.monitor-trigger{display:inline-flex;align-items:center;gap:5px;white-space:nowrap;color:var(--accent);background:var(--accent-soft);border:1px solid var(--accent-border);border-radius:5px;padding:4px 7px;font:inherit;cursor:pointer;min-height:26px}.team-monitor{padding:0;border:1px solid var(--border-strong);border-radius:var(--r-lg);width:min(1180px,calc(100vw - 48px));max-width:none;height:min(800px,calc(100dvh - 64px));max-height:none;color:var(--text);background:var(--panel);box-shadow:var(--shadow-pop);overflow:hidden}.team-monitor::backdrop{background:var(--overlay)}.monitor-shell{height:100%;display:flex;flex-direction:column;min-height:0}.monitor-heading{padding:20px 24px;display:flex;align-items:center;justify-content:space-between;gap:14px;border-bottom:1px solid var(--border);flex:none}.monitor-identity,.heading-actions{display:flex;align-items:center;gap:12px}.monitor-symbol{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--accent-border);color:var(--accent);background:var(--accent-soft);border-radius:11px}.monitor-eyebrow{font-size:10px;color:var(--muted);letter-spacing:.08em;font-weight:600}.monitor-heading h2{margin:3px 0 0;font-size:20px;font-weight:650;line-height:1.3}.team-monitor button{font-family:inherit;cursor:pointer}.heading-actions>button,.trace-heading>button,.monitor-error>button{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:7px 10px;background:var(--panel);border:1px solid var(--border-strong);border-radius:6px;color:var(--text-2);font-size:12px;min-height:32px}.heading-actions .monitor-close{padding:6px;width:32px;background:transparent;border-color:transparent}.update-label{font-size:11px;color:var(--muted);display:flex;align-items:center;gap:5px}.update-label i,.monitor-statusbar i,.node-status i,.state-pill i,.relation-footer i{width:6px;height:6px;display:inline-block;border-radius:50%;background:currentColor;flex:none}.update-label i{color:var(--ok)}.monitor-statusbar{disp